import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { GitError } from "../errors.js";

export const OID_HEX_LENGTH = 40;
export const MIN_ABBREV_LENGTH = 4;
export const DEFAULT_ABBREV_LENGTH = 7;

export function isFullOid(text) {
  return /^[0-9a-f]{40}$/.test(text);
}

function frame(type, content) {
  return Buffer.concat([Buffer.from(`${type} ${content.length}\0`), content]);
}

export function hashObject(type, content) {
  return createHash("sha1").update(frame(type, content)).digest("hex");
}

function objectPath(gitDir, oid) {
  return path.join(gitDir, "objects", oid.slice(0, 2), oid.slice(2));
}

export function objectExists(gitDir, oid) {
  return fs.existsSync(objectPath(gitDir, oid));
}

// Writes a loose object (unless it already exists) and returns its ID.
export function writeObject(gitDir, type, content) {
  const data = frame(type, content);
  const oid = createHash("sha1").update(data).digest("hex");
  const file = objectPath(gitDir, oid);
  if (fs.existsSync(file)) return oid;
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const temp = path.join(path.dirname(file), `tmp_obj_${process.pid}_${Date.now()}`);
  fs.writeFileSync(temp, zlib.deflateSync(data), { mode: 0o444 });
  fs.renameSync(temp, file);
  return oid;
}

// Returns { type, content } or null when the object does not exist.
export function readObject(gitDir, oid) {
  let compressed;
  try {
    compressed = fs.readFileSync(objectPath(gitDir, oid));
  } catch (e) {
    if (e.code === "ENOENT") return null;
    throw e;
  }
  const data = zlib.inflateSync(compressed);
  const space = data.indexOf(0x20);
  const nul = data.indexOf(0);
  const type = data.subarray(0, space).toString();
  const size = Number(data.subarray(space + 1, nul).toString());
  const content = data.subarray(nul + 1);
  if (content.length !== size) throw new GitError(`object ${oid} is corrupt`);
  return { type, content };
}

// The IDs of all objects whose ID starts with the given hex prefix (at least 2 digits).
export function findObjectsByPrefix(gitDir, prefix) {
  let names;
  try {
    names = fs.readdirSync(path.join(gitDir, "objects", prefix.slice(0, 2)));
  } catch (e) {
    if (e.code === "ENOENT" || e.code === "ENOTDIR") return [];
    throw e;
  }
  const rest = prefix.slice(2);
  return names
    .filter((name) => name.length === OID_HEX_LENGTH - 2 && name.startsWith(rest))
    .map((name) => prefix.slice(0, 2) + name)
    .sort();
}

// The shortest prefix of oid, at least DEFAULT_ABBREV_LENGTH long, that no other object shares.
export function abbreviate(gitDir, oid) {
  const others = findObjectsByPrefix(gitDir, oid.slice(0, 2)).filter((o) => o !== oid);
  let length = DEFAULT_ABBREV_LENGTH;
  while (length < OID_HEX_LENGTH && others.some((o) => o.startsWith(oid.slice(0, length)))) length++;
  return oid.slice(0, length);
}
EOF

cat > src/core/objects/modes.js <<'EOF'
// File modes as git records them in trees and in the index.
export const MODE_FILE = 0o100644;
export const MODE_EXECUTABLE = 0o100755;
export const MODE_SYMLINK = 0o120000;
export const MODE_TREE = 0o40000;

const TYPE_MASK = 0o170000;

export function isTreeMode(mode) {
  return (mode & TYPE_MASK) === MODE_TREE;
}

// Regular files and symlinks are different types; the executable bit does not change the type.
export function sameType(a, b) {
  return (a & TYPE_MASK) === (b & TYPE_MASK);
}

// The mode the index records for a file in the working tree, or null for anything git does not track.
export function modeFromStat(stat) {
  if (stat.isSymbolicLink()) return MODE_SYMLINK;
  if (stat.isFile()) return stat.mode & 0o100 ? MODE_EXECUTABLE : MODE_FILE;
  return null;
}
EOF
cat > src/core/objects/tree.js <<'EOF'
import { comparePaths, joinPath } from "../paths.js";
import { isTreeMode, MODE_TREE } from "./modes.js";
import { GitError } from "../errors.js";
import { readObject, writeObject } from "./store.js";

// Entries: { mode, name, oid }, with mode as a number.
export function parseTree(content) {
  const entries = [];
  let pos = 0;
  while (pos < content.length) {
    const space = content.indexOf(0x20, pos);
    const nul = content.indexOf(0, space);
    const mode = parseInt(content.subarray(pos, space).toString(), 8);
    const name = content.subarray(space + 1, nul).toString();
    const oid = content.subarray(nul + 1, nul + 21).toString("hex");
    entries.push({ mode, name, oid });
    pos = nul + 21;
  }
  return entries;
}

// Trees sort their entries by name, comparing a directory as if its name ended with "/".
function treeSortKey(entry) {
  return isTreeMode(entry.mode) ? `${entry.name}/` : entry.name;
}

export function serializeTree(entries) {
  const sorted = [...entries].sort((a, b) => comparePaths(treeSortKey(a), treeSortKey(b)));
  return Buffer.concat(
    sorted.flatMap((e) => [Buffer.from(`${e.mode.toString(8)} ${e.name}\0`), Buffer.from(e.oid, "hex")]),
  );
}

export function readTree(gitDir, oid) {
  const object = readObject(gitDir, oid);
  if (!object || object.type !== "tree") throw new GitError(`unable to read tree ${oid}`);
  return parseTree(object.content);
}

// All non-tree entries reachable from a tree, as a Map from path to { mode, oid }.
export function flattenTree(gitDir, oid, prefix = "", into = new Map()) {
  for (const entry of readTree(gitDir, oid)) {
    const path = joinPath(prefix, entry.name);
    if (isTreeMode(entry.mode)) flattenTree(gitDir, entry.oid, path, into);
    else into.set(path, { mode: entry.mode, oid: entry.oid });
  }
  return into;
}

// Writes the trees for a list of { path, mode, oid } entries and returns the root tree's ID.
export function writeTreeFromEntries(gitDir, entries) {
  const root = new Map();
  for (const entry of entries) {
    const parts = entry.path.split("/");
    let dir = root;
    for (const part of parts.slice(0, -1)) {
      if (!dir.has(part)) dir.set(part, new Map());
      dir = dir.get(part);
    }
    dir.set(parts.at(-1), entry);
  }
  const write = (dir) => {
    const treeEntries = [...dir].map(([name, child]) =>
      child instanceof Map ? { mode: MODE_TREE, name, oid: write(child) } : { mode: child.mode, name, oid: child.oid },
    );
    return writeObject(gitDir, "tree", serializeTree(treeEntries));
  };
  return write(root);
}
EOF

cat > src/core/objects/commit.js <<'EOF'
import { readObject } from "./store.js";

// Returns { tree, parents, author, committer, message }; author and committer are raw identity lines.
export function parseCommit(content) {
  const text = content.toString();
  const headerEnd = text.indexOf("\n\n");
  const header = headerEnd === -1 ? text : text.slice(0, headerEnd);
  const commit = { tree: null, parents: [], author: null, committer: null, message: headerEnd === -1 ? "" : text.slice(headerEnd + 2) };
  for (const line of header.split("\n")) {
    const space = line.indexOf(" ");
    const key = line.slice(0, space);
    const value = line.slice(space + 1);
    if (key === "tree") commit.tree = value;
    else if (key === "parent") commit.parents.push(value);
    else if (key === "author") commit.author = value;
