import { leadingDirectories } from "../paths.js";
import { compareEntries, readIndex, writeIndex } from "./index-file.js";

// The index in memory: entries by path. tgit v1 never creates conflict stages,
// so each path has a single entry.
export class Index {
  constructor(entries = []) {
    this.byPath = new Map(entries.map((e) => [e.path, e]));
    this.directories = null;
  }

  static read(gitDir) {
    return new Index(readIndex(gitDir));
  }

  write(gitDir) {
    writeIndex(gitDir, [...this.byPath.values()]);
  }

  get size() {
    return this.byPath.size;
  }

  get(path) {
    return this.byPath.get(path);
  }

  has(path) {
    return this.byPath.has(path);
  }

  set(entry) {
    this.byPath.set(entry.path, entry);
    this.directories = null;
  }

  delete(path) {
    this.byPath.delete(path);
    this.directories = null;
  }

  // Entries sorted as git sorts them.
  entries() {
    return [...this.byPath.values()].sort(compareEntries);
  }

  // Whether some tracked path lies inside the directory dir.
  hasEntriesInside(dir) {
    if (!this.directories) {
      this.directories = new Set([...this.byPath.keys()].flatMap(leadingDirectories));
    }
    return this.directories.has(dir);
  }
}
