import fs from "node:fs";
import path from "node:path";
import { parseOptions } from "../cli/options.js";
import { GitError } from "../core/errors.js";
import { configValue, loadConfig, setConfigValue } from "../core/repo/config.js";
import { isValidRefName } from "../core/refs/refname.js";
import { BRANCH_PREFIX, setSymbolicRef } from "../core/refs/refs.js";

const USAGE = "tgit init [-q | --quiet] [-b <branch-name> | --initial-branch=<branch-name>] [<directory>]";
const OPTIONS = [
  { key: "quiet", short: "q", long: "quiet" },
  { key: "initialBranch", short: "b", long: "initial-branch", value: true },
];
const DEFAULT_BRANCH = "master";
const DIRECTORIES = ["objects/info", "objects/pack", "refs/heads", "refs/tags"];
const CORE_CONFIG = [
  ["repositoryformatversion", "0"],
  ["filemode", "true"],
  ["bare", "false"],
  ["logallrefupdates", "true"],
];

function createDirectory(dir) {
  try {
    fs.mkdirSync(dir, { recursive: true });
  } catch (e) {
    if (e.code === "EEXIST" || e.code === "ENOTDIR") throw new GitError(`cannot mkdir ${dir}: File exists`);
    throw e;
  }
}

function run(argv, { cwd, env, stdout, stderr }) {
  const { options, args } = parseOptions(argv, OPTIONS, USAGE);
  if (args.length > 1) throw new (parseOptions.UsageError ?? Error)("too many arguments");
  const workTree = path.resolve(cwd, args[0] ?? ".");
  const gitDir = path.join(workTree, ".git");
  const reinit = fs.existsSync(path.join(gitDir, "HEAD"));

  if (!reinit) {
    const branch = options.initialBranch ?? configValue(loadConfig(env), "init.defaultBranch") ?? DEFAULT_BRANCH;
    if (!isValidRefName(`${BRANCH_PREFIX}${branch}`)) throw new GitError(`invalid initial branch name: '${branch}'`);
    createDirectory(args[0] ?? workTree);
  } else if (options.initialBranch !== undefined) {
    stderr.write(`warning: re-init: ignored --initial-branch=${options.initialBranch}\n`);
  }
  for (const dir of DIRECTORIES) fs.mkdirSync(path.join(gitDir, dir), { recursive: true });
  if (!reinit) setSymbolicRef(gitDir, "HEAD", `${BRANCH_PREFIX}${options.initialBranch ?? configValue(loadConfig(env), "init.defaultBranch") ?? DEFAULT_BRANCH}`);
  for (const [name, value] of CORE_CONFIG) setConfigValue(path.join(gitDir, "config"), "core", name, value);

  if (!options.quiet) {
    const verb = reinit ? "Reinitialized existing" : "Initialized empty";
    stdout.write(`${verb} Git repository in ${fs.realpathSync(gitDir)}/\n`);
  }
}

export default { name: "init", run };
