  { key: "type", short: "t" },
  { key: "size", short: "s" },
  { key: "print", short: "p" },
];
const GITLINK_MODE = 0o160000;

function entryType(mode) {
  if (isTreeMode(mode)) return "tree";
  return mode === GITLINK_MODE ? "commit" : "blob";
