function formatTree(content) {
  return parseTree(content)
    .map((e) => `${e.mode.toString(8).padStart(6, "0")} ${entryType(e.mode)} ${e.oid}\t${quotePath(e.name)}\n`)
    .join("");
}

function run(argv, { cwd, stdout }) {
  const repo = requireRepository(cwd);
  const { options, args } = parseOptions(argv, OPTIONS, USAGE);
  const modes = OPTIONS.filter((o) => options[o.key]);
  if (modes.length !== 1) throw new UsageError(modes.length ? "only one of -t, -s and -p can be used" : "an option is required", USAGE);
  if (args.length !== 1) throw new UsageError(args.length ? "too many arguments" : "an object is required", USAGE);

  const oid = resolveRevision(repo.gitDir, args[0]);
  const object = oid && readObject(repo.gitDir, oid);
  if (!object) throw new GitError(`Not a valid object name ${args[0]}`);
