    if (blocked) continue;
    const stat = lstatOrNull(worktreePath(repo, path));
    if (stat && !okToReplace(path, stat, kind)) continue;
    if (entry) updates.set(path, entry);
  }

  if (Object.keys(problems).length > 0) return problems;

  for (const path of removals) {
    removeWorktreeFile(repo, path);
    index.delete(path);
