    const name = basename(source.path);
    const destination = uniqueDestinations.get(name);
    if (!uniqueSources.get(name) || !destination || destination.source) continue;
    if (similarity(source, destination, MIN_BASENAME_SCORE) >= MIN_BASENAME_SCORE) recordRename(source, destination);
  }
}

// Orders pairs from the most to the least similar, preferring the same basename on equal scores.
// Unused slots (without a destination) sort last.
function comparePairs(a, b) {
  if (!a.destination) return b.destination ? 1 : 0;
  if (!b.destination) return -1;
  if (a.score === b.score) return b.nameScore - a.nameScore;
  return b.score - a.score;
}

// Keeps the best few candidates for one destination in fixed slots, replacing the worst one.
function recordIfBetter(slots, pair) {
  let worst = 0;
  for (let i = 1; i < slots.length; i++) {
    if (comparePairs(slots[i], slots[worst]) > 0) worst = i;
  }
  if (comparePairs(slots[worst], pair) > 0) slots[worst] = pair;
}

function findSimilarRenames(sources, destinations) {
  const pairs = [];
  for (const destination of destinations.filter((d) => !d.source)) {
    const slots = Array.from({ length: CANDIDATES_PER_DESTINATION }, () => ({ destination: null }));
    for (const source of sources) {
      const score = similarity(source, destination, MIN_SCORE);
      recordIfBetter(slots, { source, destination, score, nameScore: basenameScore(source.path, destination.path) });
    }
    pairs.push(...slots);
  }
  pairs.sort(comparePairs);
  for (const { source, destination, score } of pairs) {
    if (!destination || score < MIN_SCORE) break;
    if (destination.source || source.used) continue;
    recordRename(source, destination);
  }
}

// Takes the deleted and the added files as { path, mode, oid }, each sorted by path, and returns
// a map from each renamed destination path to its source path.
export function detectRenames(gitDir, deleted, added) {
  let sources = deleted.map((file) => new Candidate(gitDir, file));
  const destinations = added.map((file) => new Candidate(gitDir, file));
  const unused = () => sources.filter((source) => !source.used);
  const renames = () => new Map(destinations.filter((d) => d.source).map((d) => [d.path, d.source.path]));

  findIdenticalRenames(sources, destinations);
  sources = unused();
  if (sources.length === 0 || destinations.every((d) => d.source)) return renames();
  findBasenameRenames(sources, destinations);
  sources = unused();
  if (sources.length === 0 || destinations.every((d) => d.source)) return renames();
  findSimilarRenames(sources, destinations);
  return renames();
}
