  return path.join(gitDir, "index");
}

// The index entries in order; an empty list when there is no index file yet.
export function readIndex(gitDir) {
  let data;
  try {
    data = fs.readFileSync(indexFile(gitDir));
  } catch (e) {
    if (e.code === "ENOENT") return [];
    throw e;
  }
  return parseIndex(data);
}

