export function isFullOid(text) {
  return /^[0-9a-f]{40}$/.test(text);
}

function frame(type, content) {
  return Buffer.concat([Buffer.from(`${type} ${content.length}\0`), content]);
}

export function hashObject(type, content) {
  return createHash("sha1").update(frame(type, content)).digest("hex");
}

function objectPath(gitDir, oid) {
  return path.join(gitDir, "objects", oid.slice(0, 2), oid.slice(2));
}

export function objectExists(gitDir, oid) {
  return fs.existsSync(objectPath(gitDir, oid));
}

// Writes a loose object (unless it already exists) and returns its ID.
export function writeObject(gitDir, type, content) {
  const data = frame(type, content);
  const oid = createHash("sha1").update(data).digest("hex");
