// Prints the TREE extension of an index file as text (scratch tool).
import fs from "node:fs";
const data = fs.readFileSync(process.argv[2]);
const count = data.readUInt32BE(8);
let pos = 12;
for (let i = 0; i < count; i++) {
  const nameEnd = data.indexOf(0, pos + 62);
  pos += Math.floor((nameEnd - pos + 8) / 8) * 8;
}
let out = "";
while (pos < data.length - 20) {
  const sig = data.toString("latin1", pos, pos + 4);
  const size = data.readUInt32BE(pos + 4);
  const ext = data.subarray(pos + 8, pos + 8 + size);
  if (sig === "TREE") {
    let p = 0;
    while (p < ext.length) {
      const nul = ext.indexOf(0, p);
      const nl = ext.indexOf(10, nul);
      const [n, sub] = ext.toString("latin1", nul + 1, nl).split(" ");
      out += `${JSON.stringify(ext.toString("utf8", p, nul))} ${n} ${sub}`;
      p = nl + 1;
      if (Number(n) >= 0) { out += " " + ext.toString("hex", p, p + 20); p += 20; }
      out += "\n";
    }
  } else out += `ext ${sig}\n`;
  pos += 8 + size;
}
process.stdout.write(out || "(no extensions)\n");
