function run(argv, { cwd, stdout, stderr }) {
  const repo = requireRepository(cwd);
  const { options, args } = parseOptions(argv, OPTIONS, USAGE);
  const head = readHead(repo.gitDir);
  const newBranch = options.create;
  let target;
  let targetOid;

  if (newBranch !== undefined) {
    if (args.length > 1) throw new UsageError("too many arguments", USAGE);
    if (!isValidBranchName(newBranch)) throw new GitError(`'${newBranch}' is not a valid branch name`);
    target = `${BRANCH_PREFIX}${newBranch}`;
    if (resolveRef(repo.gitDir, target)?.oid) throw new GitError(`a branch named '${newBranch}' already exists`);
    targetOid = args.length > 0 ? resolveCommit(repo.gitDir, args[0]) : head.oid;
    if (args.length > 0 && !targetOid) throw new GitError(`invalid reference: ${args[0]}`);
  } else {
    if (args.length === 0) throw new GitError("missing branch or commit argument");
    if (args.length > 1) throw new GitError("only one reference expected");
    target = `${BRANCH_PREFIX}${args[0]}`;
    targetOid = resolveRef(repo.gitDir, target)?.oid;
    if (!targetOid) {
      if (resolveCommit(repo.gitDir, args[0])) throw new GitError(`a branch is expected, got '${args[0]}'`);
      throw new GitError(`invalid reference: ${args[0]}`);
    }
  }

  // A new branch on an unborn branch is unborn too: only HEAD changes.
  if (!targetOid) {
    setSymbolicRef(repo.gitDir, "HEAD", target);
    stderr.write(`Switched to a new branch '${newBranch}'\n`);
    return 0;
  }

  const index = Index.read(repo.gitDir);
  const problems = twoWayMerge(repo, index, head.oid, targetOid);
  if (problems) {
    reportProblems(problems, stderr);
    return CONFLICT;
  }
  // Like the real git after a checkout, record the trees that already exist.
  index.cacheTree = updateCacheTree(repo.gitDir, index.entries(), index.cacheTree, { repair: true });
  index.write(repo.gitDir);
  showLocalChanges(repo, index, targetOid, stdout);

  if (newBranch !== undefined) updateRef(repo.gitDir, target, targetOid);
  if (target === head.branch) {
    stderr.write(`Already on '${args[0]}'\n`);
    return 0;
  }
  setSymbolicRef(repo.gitDir, "HEAD", target);
  stderr.write(newBranch !== undefined ? `Switched to a new branch '${newBranch}'\n` : `Switched to branch '${args[0]}'\n`);
}

export default { name: "switch", run };

